import React from 'react';
import { useNavigate } from 'react-router-dom';
import BottomNav from '../components/BottomNav';

function DashboardCustomer() {
  const navigate = useNavigate();
  const categories = ['Desain', 'Editing', 'Tulisan', 'Teknologi'];
  const orders = [
    { title: 'Desain Logo Cafe Kopi Kekinian', price: 'Rp 250k', status: 'Aktif', deadline: 'Besok, 17:00', worker: 'Farhan M.', role: 'Desainer Grafis' },
    { title: 'Video Reels Promosi Launching Produk', price: 'Rp 500k', status: 'Dikerjakan', deadline: '3 Hari Lagi', worker: 'Sarah K.', role: 'Video Editor' }
  ];

  return (
    <div style={{ maxWidth: '402px', margin: '0 auto', background: '#F8F9FA', minHeight: '100vh', padding: '16px 20px 80px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
        <h1 style={{ fontSize: '20px', fontWeight: 800, color: '#0D9488', cursor: 'pointer' }} onClick={() => navigate('/')}>WORKIE</h1>
        <div style={{ display: 'flex', gap: '16px', fontSize: '20px' }}>
          <span>🔔</span>
          <span style={{ cursor: 'pointer' }} onClick={() => navigate('/')}>👤</span>
        </div>
      </div>
      <div><p style={{ color: '#475569' }}>Selamat Pagi,</p><h2>Halo, Andi Wijaya!</h2></div>

      <div style={{ background: 'white', padding: '16px', borderRadius: '16px', margin: '16px 0' }}>
        <div style={{ display: 'flex', alignItems: 'center', background: '#F8F9FA', borderRadius: '12px', padding: '0 12px', marginBottom: '12px' }}>
          <span>🔍</span>
          <input type="text" placeholder="Kamu butuh bantuan apa?" style={{ flex: 1, padding: '12px 0', border: 'none', background: 'transparent', fontSize: '14px' }} />
        </div>
        <button onClick={() => navigate('/ai-planner')} style={{ width: '100%', padding: '12px', background: '#0D9488', color: 'white', border: 'none', borderRadius: '12px', fontSize: '14px', fontWeight: 600 }}>+ Buat Order Instan</button>
        <p style={{ fontSize: '13px', color: '#475569', marginTop: '8px' }}>Ketik kebutuhan kerjamu, AI kami buatkan deskripsinya!</p>
      </div>

      <div style={{ marginBottom: '16px' }}>
        <h3>Kategori Terpopuler</h3>
        <div style={{ display: 'flex', gap: '10px', marginTop: '8px' }}>
          {categories.map((cat, i) => (<span key={i} style={{ padding: '8px 16px', background: 'white', borderRadius: '20px', border: '1px solid #E2E8F0', fontSize: '14px' }}>{cat}</span>))}
        </div>
      </div>

      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between' }}><h3>Order Anda Saat Ini</h3><span style={{ color: '#0D9488', fontSize: '14px', cursor: 'pointer' }} onClick={() => navigate('/order-status')}>Lihat Semua</span></div>
        {orders.map((order, i) => (
          <div key={i} style={{ background: 'white', padding: '16px', borderRadius: '12px', marginTop: '12px' }}>
            <span style={{ display: 'inline-block', padding: '4px 12px', borderRadius: '12px', fontSize: '12px', fontWeight: 600, background: order.status === 'Aktif' ? '#D1FAE5' : '#FEF3C7', color: order.status === 'Aktif' ? '#065F46' : '#92400E' }}>{order.status}</span>
            <h4 style={{ margin: '8px 0 4px' }}>{order.title}</h4>
            <p style={{ fontWeight: 700, color: '#0D9488' }}>{order.price}</p>
            <div style={{ display: 'flex', gap: '12px', fontSize: '13px', color: '#475569' }}>
              <span>{order.worker}</span>
              <span style={{ color: '#0D9488', fontWeight: 500 }}>{order.role}</span>
              <span>📅 {order.deadline}</span>
            </div>
          </div>
        ))}
      </div>
      <BottomNav role="customer" />
    </div>
  );
}

export default DashboardCustomer;
